(function(){
'use strict';
var $=function(id){return document.getElementById(id);};
var prefs={};try{prefs=JSON.parse(localStorage.getItem('still-prefs')||'{}');}catch(e){}
function apply(){document.querySelector('.room').textContent=prefs.room||'YOUR SPACE';$('note').textContent=prefs.note||'There’s no rush. Enjoy your evening.';}
function tick(){var now=new Date(),h=now.getHours(),m=String(now.getMinutes()).padStart(2,'0'),text=(prefs.hour24?String(h).padStart(2,'0'):(h%12||12))+':'+m; $('clock').innerHTML=text+(prefs.hour24?'':'<span class="period">'+(h<12?'AM':'PM')+'</span>');$('ambient-clock').textContent=text;$('date').textContent=now.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase();$('ambient-date').textContent=$('date').textContent;}
function toast(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(function(){$('toast').style.display='none';},6000);}
var apps=[{id:'youtube',name:'YouTube',logo:'▶ YouTube',color:'#f0e9dd'},{id:'netflix',name:'Netflix',logo:'NETFLIX',color:'#e35a52'},{id:'prime',name:'Prime Video',logo:'prime video',color:'#87bad3'},{id:'source',name:'HDMI & inputs',logo:'↳ HDMI',color:'#c9d5b4'},{id:'home',name:'All TV apps',logo:'⊞ Apps',color:'#c9d5b4'}];
apps.forEach(function(app){var b=document.createElement('button');b.className='app';b.style.setProperty('--app-color',app.color);b.innerHTML='<span class="logo">'+app.logo+'</span><span class="app-caption">'+app.name+'<span>↗</span></span>';b.onclick=function(){b.disabled=true;toast('Sending '+app.name+' request to your TV…');fetch('/api/launch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:app.id})}).then(function(r){return r.json().then(function(data){if(!r.ok)throw Error(data.error||'TV unavailable');return data;});}).then(function(){toast('Request sent. If the app stays closed, use All TV apps.');}).catch(function(e){toast(e.message);}).finally(function(){b.disabled=false;});};if($('apps').querySelector('p'))$('apps').innerHTML='';$('apps').appendChild(b);});
function settings(){ $('room-name').value=prefs.room||'';$('note-input').value=prefs.note||'';$('format').checked=!!prefs.hour24;if($('preferences').showModal)$('preferences').showModal();else $('preferences').setAttribute('open','');}
$('settings').onclick=settings;$('note-button').onclick=settings;
$('preferences').querySelector('form').onsubmit=function(){prefs={room:$('room-name').value.trim(),note:$('note-input').value.trim(),hour24:$('format').checked};try{localStorage.setItem('still-prefs',JSON.stringify(prefs));}catch(e){toast('Browser storage unavailable; changes apply for this visit.');}apply();tick();};
$('ambient').onclick=function(){$('ambient-view').hidden=false;$('home').hidden=true;$('wake').focus();};
function wake(){$('ambient-view').hidden=true;$('home').hidden=false;$('ambient').focus();}
$('wake').onclick=wake;
document.addEventListener('keydown',function(e){if((e.key==='Escape'||e.keyCode===10009)&&!$('ambient-view').hidden){e.preventDefault();wake();return;}if($('preferences').open)return;var dirs={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]},d=dirs[e.key];if(!d)return;e.preventDefault();var els=Array.prototype.slice.call(document.querySelectorAll('button:not(:disabled)')).filter(function(b){return b.offsetParent!==null;});var current=document.activeElement;if(els.indexOf(current)<0){els[0].focus();return;}var r=current.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2,best=null,score=Infinity;els.forEach(function(b){if(b===current)return;var q=b.getBoundingClientRect(),dx=q.left+q.width/2-x,dy=q.top+q.height/2-y,forward=dx*d[0]+dy*d[1],cross=Math.abs(dx*d[1]+dy*d[0]);if(forward>10){var s=forward+cross*3;if(s<score){score=s;best=b;}}});if(best)best.focus();});
apply();tick();setInterval(tick,1000);
})();
